css:
.note-to-mp {
  max-width:677px;margin:0 auto;padding:0 14px 36px;background:#FFFFFF;color:#25282D;
  font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif;font-size:16px;line-height:1.86!important;overflow-x:hidden;word-break:break-word;

}
.note-to-mp p {color:#25282D;margin:0 0 16px!important;font-size:15px;line-height:1.72!important;letter-spacing:.01em;text-align:left!important;}
.note-to-mp h1 {margin:0 0 32px;font-size:24px;font-weight:750;line-height:1.32!important;padding:20px;border:1px solid #4B5563;border-radius:0;background:#111827;color:#FFFFFF;box-shadow:none;font-family:Menlo,'PingFang SC',sans-serif;letter-spacing:.01em;}
.note-to-mp h2 {margin:44px 0 20px!important;font-size:21px;font-weight:750;line-height:1.35!important;padding:0 0 12px;border:none;border-bottom:1px solid #4B5563;border-radius:0;background:#FFFFFF;color:#111827;}
.note-to-mp .wechatpb-heading-label {font-size:10px;font-weight:650;line-height:1.2!important;letter-spacing:2px;display:block;margin:0 0 -3px;padding:0;background:transparent;color:#D1D5DB;font-family:Menlo,monospace;font-size:36px;line-height:1!important;letter-spacing:-2px;}
.note-to-mp h3 {margin:26px 0 13px!important;font-size:15px;font-weight:700;line-height:1.5!important;padding:9px 11px;border:1px solid #9CA3AF;border-radius:0;background:#F3F4F6;color:#111827;font-family:Menlo,'PingFang SC',sans-serif;}
.note-to-mp h4,.note-to-mp h5,.note-to-mp h6 {margin:28px 0 15px!important;color:#25282D;font-size:16px;font-weight:650;line-height:1.5!important;}
.note-to-mp strong {padding:0 2px;font-weight:700;padding:0 1px 2px;border-bottom:2px solid #4B5563;background:transparent;color:#111827;}
.note-to-mp em {color:#4B5563;font-style:italic;}
.note-to-mp a {color:#4B5563;text-decoration:none;border-bottom:1px solid #4B5563;}
.note-to-mp blockquote {margin:0 0 26px!important;padding:18px;border:1px solid #9CA3AF;border-radius:0;background:#F9FAFB;color:#374151;box-shadow:none;font-family:Menlo,'PingFang SC',sans-serif;}
.note-to-mp blockquote p {margin:0!important;color:inherit!important;font-size:15px;line-height:1.78!important;text-align:inherit!important;}
.note-to-mp ul,.note-to-mp ol {margin:0 0 24px;line-height:1.82!important;padding:0;list-style-position:inside;color:#30343A;}
.note-to-mp li {margin:0;padding:9px 8px;border-bottom:1px solid #D1D5DB;font-family:Menlo,'PingFang SC',sans-serif;font-size:14px;}
.note-to-mp li::marker {color:#4B5563;font-weight:700;}
.note-to-mp code {padding:2px 6px;border:1px solid #E2E8F0;border-radius:4px;background:#F1F5F9;color:#334155;font-family:Menlo,Monaco,Consolas,monospace;font-size:14px;}
.note-to-mp .code-section {margin:0 0 26px;overflow:hidden;padding:0;border:1px solid #111827;border-radius:0;background:#111827;box-shadow:none;}
.note-to-mp .code-section pre {margin:0;max-height:360px;padding:17px;overflow:auto;background:transparent;white-space:pre-wrap!important;word-break:break-all!important;}
.note-to-mp .code-section code {display:block;padding:0;border:none;background:transparent;color:#E5E7EB;line-height:1.65!important;}
.note-to-mp img {width:auto;max-width:100%;height:auto;display:block;margin:28px auto;box-sizing:border-box;border:1px solid #9CA3AF;border-radius:0;box-shadow:none;}
.note-to-mp hr {height:1px;margin:48px 0 32px;border:none;height:1px;background:#4B5563;}
.note-to-mp table {width:100%;margin:0 0 26px;box-sizing:border-box;table-layout:fixed;font-size:14px;border-collapse:collapse;border:1px solid #4B5563;font-family:Menlo,'PingFang SC',sans-serif;}
.note-to-mp th {box-sizing:border-box;padding:10px 12px;vertical-align:middle;text-align:left;white-space:normal;word-break:break-word;overflow-wrap:anywhere;background:#111827;color:#FFFFFF;border:1px solid #4B5563;}
.note-to-mp td {box-sizing:border-box;padding:10px 12px;vertical-align:middle;text-align:left;white-space:normal;word-break:break-word;overflow-wrap:anywhere;color:#25282D;background:#FFFFFF;border:1px solid #D1D5DB;}
